<script>
(function(){var form=document.getElementById('display-preferences-form');if(!form)return;var p=@json($preferences),body=document.body;function apply(){body.classList.remove('light','dark','light-sidebar','dark-sidebar','sidebar-mini','navbar-static');['white','cyan','black','purple','orange','green','red'].forEach(function(t){body.classList.remove('theme-'+t);});body.classList.add(p.theme==='dark'?'dark':'light',p.sidebar_color==='dark'?'dark-sidebar':'light-sidebar','theme-'+p.color_theme);if(p.sidebar==='compact')body.classList.add('sidebar-mini');if(p.navbar==='static')body.classList.add('navbar-static');}form.addEventListener('change',function(e){var t=form.querySelector('[name=theme_choice]:checked'),s=form.querySelector('[name=sidebar_color_choice]:checked'),m=document.getElementById('mini_sidebar_setting'),n=document.getElementById('sticky_header_setting');if(t)form.querySelector('#preference-theme').value=t.value==='2'?'dark':'light';if(s)form.querySelector('#preference-sidebar-color').value=s.value==='2'?'dark':'light';if(e.target.dataset.themeColor)form.querySelector('#preference-color-theme').value=e.target.dataset.themeColor;p.theme=form.querySelector('#preference-theme').value;p.sidebar_color=form.querySelector('#preference-sidebar-color').value;p.color_theme=form.querySelector('#preference-color-theme').value;p.sidebar=m&&m.checked?'compact':'expanded';p.navbar=n&&n.checked?'sticky':'static';apply();});form.addEventListener('submit',function(){var m=document.getElementById('mini_sidebar_setting'),n=document.getElementById('sticky_header_setting');p.sidebar=m&&m.checked?'compact':'expanded';p.navbar=n&&n.checked?'sticky':'static';form.querySelector('input[name=sidebar][type=hidden]').value='expanded';form.querySelector('input[name=navbar][type=hidden]').value='static';form.querySelector('#preference-theme').value=p.theme;form.querySelector('#preference-sidebar-color').value=p.sidebar_color;form.querySelector('#preference-color-theme').value=p.color_theme;});form.querySelectorAll('[data-theme-color]').forEach(function(b){b.addEventListener('click',function(){form.querySelector('#preference-color-theme').value=b.dataset.themeColor;p.color_theme=b.dataset.themeColor;apply();});});apply();}());
</script>
